```typescript
import { createClient } from '@supabase/supabase-js';
import { GoogleGenerativeAI, GoogleGenerativeAIStream } from "@google/generative-ai";
import { settings, accessToken } from './appState';

const apiKey: string | undefined = process.env.API_KEY;

export const getGeminiApiKey = async (): Promise<string> => {
    // 1. Check for environment variable
    const envKey = apiKey;

    if (envKey && typeof envKey === 'string' && envKey.trim() !== '' && !envKey.includes("UNDEFINED")) {
        return envKey;
    }

    // 2. Fallback to DB
    if (!settings.supabaseUrl || !settings.supabaseKey || !accessToken) {
        throw new Error("Faltan credenciales de sesión para obtener la clave de IA.");
    }

    const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
        global: { headers: { Authorization: `Bearer ${accessToken}` } }
    });

    const { data, error } = await client
        .from('app_secrets')
        .select('value')
        .eq('key_name', 'GEMINI_API_KEY')
        .single();

    if (error || !data) {
        console.error("Error fetching API Key:", error);
        throw new Error("No se pudo obtener la clave de IA (ni en Vercel ni en Supabase).");
    }

    return data.value;
};

export const generateContent = async (text: string, history: Array<{ role: 'user' | 'model', parts: Array<{ text: string }> }>) => {
    const ai = new GoogleGenerativeAI(await getGeminiApiKey());

    const model = ai.getGenerativeModel({ model: "gemini-pro" });

    // Build the chat history in the format required by the Google Generative AI library.
    const contents = history.map(item => ({ role: item.role === 'user' ? 'user' : 'model', parts: [{ text: item.parts[0].text }] }));

    const result = await model.generateContent({
        contents: [...contents, { role: 'user', parts: [{ text }] }],
    });

    const response = await result.response;
    const textResult = response.text();
    return textResult;
};
```


