const createFreshClient = (settings: SupabaseSettings, accessToken?: string): SupabaseClient | null => {
  let cleanUrl = settings.supabaseUrl.trim();
  if (!cleanUrl.startsWith('http')) cleanUrl = `https://${cleanUrl}`;
  cleanUrl = cleanUrl.replace(/\/$/, "");
  if (cleanUrl && settings.supabaseKey) {
    try {
        const options: any = { auth: { persistSession: !accessToken, autoRefreshToken: !accessToken, detectSessionInUrl: !accessToken } };
        if (accessToken) options.global = { headers: { Authorization: `Bearer ${accessToken}` } };
        return createClient(cleanUrl, settings.supabaseKey, options);
    } catch (e) { console.error("Client creation failed:", e); return null; }
  }
  return null;
};

const base64ToBlob = (base64: string, mimeType: string = 'image/jpeg'): Blob => {
  const byteString = atob(base64.split(',')[1]);
  const ab = new ArrayBuffer(byteString.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
  return new Blob([ab], { type: mimeType });
};

