export const saveEventToSupabase = async (event: DogEvent, settings: SupabaseSettings, accessToken?: string): Promise<{ success: boolean; error?: string; photoUrl?: string; newId?: string }> => {
    const client = createFreshClient(settings, accessToken);
    if (!client) return { success: false, error: "Error iniciando cliente." };
    if (!event.petId) return { success: false, error: "Falta ID de Mascota." };
    let publicPhotoUrl = null;
    if (event.photoBase64) {
        try {
            const blob = base64ToBlob(event.photoBase64);
            const fileName = `${event.petId}/${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
            const { error: uploadError } = await client.storage.from('dog_photos').upload(fileName, blob, { contentType: 'image/jpeg', upsert: true });
            if (uploadError) {
                if ((uploadError as any).statusCode === '403' || (uploadError as any).code === '42501') return { success: false, error: `⛔ No tienes permiso para subir fotos.` };
                return { success: false, error: `Error subiendo foto: ${uploadError.message}` };
            }
            const { data: urlData } = client.storage.from('dog_photos').getPublicUrl(fileName);
            publicPhotoUrl = urlData.publicUrl;
        } catch (err: any) { return { success: false, error: `Error imagen: ${err.message}` }; }
    }
    try {
        let cleanTime = event.time; if (cleanTime.length === 5) cleanTime += ":00";
        const payload = { id: event.id, title: event.title, record_type: event.recordType, date: event.date, time: cleanTime, health_status: event.healthStatus || null, weight: (event.weight !== undefined && event.weight !== null && !isNaN(Number(event.weight))) ? Number(event.weight) : null, description: event.description, photo_url: publicPhotoUrl || event.photoUrl, pet_id: event.petId, user_id: event.userId };
        const { data, error: insertError } = await client.from('events').upsert(payload).select().single();
        if (insertError) {
            if (insertError.code === '42501') return { success: false, error: "⛔ Acceso Denegado." };
            return { success: false, error: `DB Error: ${insertError.message}` };
        }
        return { success: true, photoUrl: publicPhotoUrl || undefined, newId: data?.id };
    } catch (err: any) { return { success: false, error: `App Error: ${err.message}` }; }
};

export const deleteEvent = async (eventId: string, photoUrl: string | undefined, settings: SupabaseSettings, accessToken?: string): Promise<{ success: boolean; error?: string }> => {
    const client = createFreshClient(settings, accessToken);
    if (!client) return { success: false, error: "Error de cliente." };
    try {
        const { error: dbError } = await client.from('events').delete().eq('id', eventId);
        if (dbError) {
            if (dbError.code === '42501') return { success: false, error: "⛔ Acceso Denegado." };
            return { success: false, error: dbError.message };
        }
        if (photoUrl) {
            const parts = photoUrl.split('/');
            const fileName = parts[parts.length - 1];
            if (fileName) await client.storage.from('dog_photos').remove([`${fileName}`]);
        }
        return { success: true };
    } catch (e: any) { return { success: false, error: e.message }; }
};

export const searchEvents = async (params: EventSearchParams, settings: SupabaseSettings, accessToken?: string): Promise<DogEvent[]> => {
    const client = createFreshClient(settings, accessToken);
    if (!client) return [];
    let query = client.from('events').select('*');
    if (params.petId) query = query.eq('pet_id', params.petId);
    else return [];
    if (params.recordType) query = query.eq('record_type', params.recordType);
    if (params.startDate) query = query.gte('date', params.startDate);
    if (params.endDate) query = query.lte('date', params.endDate);
    if (params.searchTitle) query = query.ilike('title', `%${params.searchTitle}%`);
    query = query.order('date', { ascending: false }).order('time', { ascending: false });
    if (params.page !== undefined && params.pageSize !== undefined) {
        const from = params.page * params.pageSize;
        const to = from + params.pageSize - 1;
        query = query.range(from, to);
    } else if (params.limit) query = query.limit(params.limit);
    else query = query.limit(50);
    const { data, error } = await query;
    if (error) throw new Error(error.message);
    return (data || []).map((row: any) => ({ id: row.id, title: row.title, recordType: row.record_type as RecordType, date: row.date, time: row.time.substring(0, 5), healthStatus: row.health_status, weight: row.weight, description: row.description, photoUrl: row.photo_url, petId: row.pet_id, userId: row.user_id, synced: true }));
};
