export const consultAssistant = async (history: ChatMessage[], settings: SupabaseSettings, petId: string, accessToken?: string): Promise<{ text: string, events?: DogEvent[] }> => {
    const apiKey = await getGeminiApiKey(settings, accessToken);
    const today = new Date().toISOString().split('T')[0];
    const contents = history.map(msg => ({ role: msg.role === 'assistant' ? 'model' : 'user', parts: [{ text: msg.text }] }));
    const lastMessageIndex = contents.length - 1;
    if (lastMessageIndex >= 0 && contents[lastMessageIndex].role === 'user') {
        contents[lastMessageIndex].parts[0].text = `Hoy es ${today}. ${contents[lastMessageIndex].parts[0].text}`;
    }
    const config = { systemInstruction: CONSULTANT_INSTRUCTION, tools: [{ functionDeclarations: [queryEventsTool] }] };
    let response = await generateWithFallback(apiKey, contents, config);
    let foundEvents: DogEvent[] = [];
    let functionCalls = response.functionCalls;

    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0]; 
        if (call.name === 'query_events') {
            const args: any = call.args;
            try {
                foundEvents = await searchEvents({
                    recordType: args.recordType,
                    startDate: args.startDate,
                    endDate: args.endDate,
                    limit: args.limit,
                    petId: petId 
                }, settings, accessToken);
            } catch (e) { console.error("Supabase Search Error", e); }

            const minimalEvents = foundEvents.map(e => ({ date: e.date, time: e.time, type: e.recordType, title: e.title, status: e.healthStatus, desc: e.description }));
            const functionResponseParts = [{ functionResponse: { name: 'query_events', response: { result: minimalEvents }, id: call.id } }];
            const newContents = [...contents, { role: 'model', parts: response.candidates![0].content.parts }, { role: 'user', parts: functionResponseParts }];
            response = await generateWithFallback(apiKey, newContents, { systemInstruction: CONSULTANT_INSTRUCTION });
        }
    }
    return { text: response.text || "No pude generar una respuesta.", events: foundEvents.length > 0 ? foundEvents : undefined };
};

