// --- NEW: Consultant Logic with Tool Use ---

const queryEventsTool: FunctionDeclaration = {
    name: 'query_events',
    description: 'Busca eventos en la base de datos. Útil para contestar preguntas sobre historial médico, cacas, comida, etc.',
    parameters: {
        type: Type.OBJECT,
        properties: {
