                                <button 
                                    onClick={() => handleToggleTask(task)}
                                    className={`w-6 h-6 rounded border flex items-center justify-center transition-colors ${task.is_completed ? 'bg-green-500 border-green-500 text-white' : 'border-slate-300 bg-white'}`}
                                >
