                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* INPUT AREA (Only visible on Notes tab) */}
            {activeTab === 'notes' && (
                <>
                    {mentionQuery !== null && filteredMembers.length > 0 && (
                        <div className="absolute bottom-24 left-4 bg-white border border-slate-200 shadow-xl rounded-xl p-2 w-64 z-50">
