// services/supabaseService.ts
import { createClient } from '@supabase/supabase-js';

const cleanUrl = (url: string) => {
  return url.replace(/^"|"$/g, '').trim();
};

const createFreshClient = (supabaseUrl: string, supabaseKey: string, accessToken?: string) => {
  const url = cleanUrl(supabaseUrl);
  let options = {
    auth: {
      persistSession: true,
    },
  };
  if (accessToken) {
    options = {
      ...options,
      global: {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      },
    };
  }
  return createClient(url, supabaseKey, options);
};

export const createSupabaseClient = (supabaseUrl: string, supabaseKey: string, accessToken?: string) => {
  return createFreshClient(supabaseUrl, supabaseKey, accessToken);
};
