export const detectTaskFromNote = async (
    message: string, 
    mentionedUsers: {id: string, name: string}[],
    settings: SupabaseSettings,
    accessToken?: string
): Promise<{ title: string, assignedToId: string | null } | null> => {

    const apiKey = await getGeminiApiKey(settings, accessToken);
    const usersContext = mentionedUsers.length > 0 
        ? mentionedUsers.map(u => `${u.name} (ID: ${u.id})`).join(", ")
        : "Ninguno";

    const prompt = `
    Analiza este mensaje del tablón de equipo: "${message}".
    Usuarios mencionados disponibles: [${usersContext}].

    ¿El mensaje contiene claramente una tarea, orden, recordatorio o solicitud de acción?

    - Si SÍ y va dirigida a alguien específico: Devuelve JSON con "title" (resumen corto infinitivo) y "assignedToId" (el ID del usuario).
    - Si SÍ pero es una tarea general (ej: "Hay que comprar pienso", "Limpiar el patio") o no menciona a nadie: Devuelve JSON con "title" y "assignedToId": null.
    - Si NO (es solo un comentario, saludo, aviso informativo): Devuelve null.

    Ejemplos:
