    - "Comprar bolsas de caca" -> {"title": "Comprar bolsas de caca", "assignedToId": null}
    - "@Maria ¿qué tal está?" -> null
    `;

    const config = {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                title: { type: Type.STRING },
                assignedToId: { type: Type.STRING, nullable: true }, // Allow null for general tasks
            },
            nullable: true
        }
    };

    try {
        const response = await generateWithFallback(apiKey, { parts: [{ text: prompt }] }, config);
        if (!response.text) return null;
        const result = JSON.parse(response.text);
        // We return the result even if assignedToId is null, as long as title exists
        if (!result || !result.title) return null;
        return result;
    } catch (e) {
        console.error("Task detection failed", e);
        return null;
    }
};
