                                            {note.user_id === currentUserId && <button onClick={() => setDeletingNoteId(note.id)} className="p-1 hover:bg-slate-100 rounded text-slate-300 hover:text-red-400"><Icons.Trash className="w-3.5 h-3.5"/></button>}
                                        </>
