export const consultAssistant = async (
    history: ChatMessage[], 
    settings: SupabaseSettings,
    petId: string, 
    accessToken?: string 
): Promise<{ text: string, events?: DogEvent[] }> => {

    const apiKey = await getGeminiApiKey(settings, accessToken);
    const today = new Date().toISOString().split('T')[0];

    // Build contents from history
    const contents = history.map(msg => ({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: msg.text }]
    }));

    // Inject context
    const lastMessageIndex = contents.length - 1;
    if (lastMessageIndex >= 0 && contents[lastMessageIndex].role === 'user') {
        const originalText = contents[lastMessageIndex].parts[0].text;
        contents[lastMessageIndex].parts[0].text = `Hoy es ${today}. ${originalText}`;
    }

    const config = {
        systemInstruction: CONSULTANT_INSTRUCTION,
        tools: [{ functionDeclarations: [queryEventsTool] }]
    };

    // 1. Initial Call (Uses Fallback)
    let response = await generateWithFallback(apiKey, contents, config);

    let foundEvents: DogEvent[] = [];
    let functionCalls = response.functionCalls;

    // Step 2: Handle Function Calls (if any)
    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0]; 

        if (call.name === 'query_events') {
            const args: any = call.args;
            try {
                foundEvents = await searchEvents({
                    recordType: args.recordType,
                    startDate: args.startDate,
                    endDate: args.endDate,
                    limit: args.limit,
                    petId: petId 
                }, settings, accessToken);
            } catch (e) {
                console.error("Supabase Search Error", e);
            }

            const minimalEvents = foundEvents.map(e => ({
                date: e.date,
                time: e.time,
                type: e.recordType,
                title: e.title,
                status: e.healthStatus,
                desc: e.description
            }));

            const functionResponseParts = [
                {
                    functionResponse: {
                        name: 'query_events',
                        response: { result: minimalEvents },
                        id: call.id
                    }
                }
            ];

            const newContents = [
                ...contents,
                { role: 'model', parts: response.candidates![0].content.parts },
                { role: 'user', parts: functionResponseParts }
            ];

            // 2. Second Call (Tool Result - Uses Fallback)
            // Note: We pass the config again but without tool definition technically needed, 
            // but keeping it maintains context instructions.
            response = await generateWithFallback(apiKey, newContents, {
                systemInstruction: CONSULTANT_INSTRUCTION
            });
        }
    }

    return {
        text: response.text || "No pude generar una respuesta.",
        events: foundEvents.length > 0 ? foundEvents : undefined
    };
};

// --- NEW: TASK DETECTION ---
export const detectTaskFromNote = async (
    message: string, 
    mentionedUsers: {id: string, name: string}[],
    settings: SupabaseSettings,
    accessToken?: string
): Promise<{ title: string, assignedToId: string | null } | null> => {

    // REMOVED: The check "if (mentionedUsers.length === 0) return null;" 
    // Now we allow task detection even without mentions (General Tasks).

    const apiKey = await getGeminiApiKey(settings, accessToken);
    const usersContext = mentionedUsers.length > 0 
        ? mentionedUsers.map(u => `${u.name} (ID: ${u.id})`).join(", ")
        : "Ninguno";

    const prompt = `
    Analiza este mensaje del tablón de equipo: "${message}".
    Usuarios mencionados disponibles para asignar: [${usersContext}].

    ¿El mensaje contiene claramente una tarea, orden, recordatorio o solicitud de acción?

    - Si SÍ y va dirigida a alguien específico: Devuelve JSON con "title" (resumen corto infinitivo) y "assignedToId" (el ID del usuario).
    - Si SÍ pero es una tarea general (ej: "Hay que comprar pienso", "Limpiar el patio") o no menciona a nadie: Devuelve JSON con "title" y "assignedToId": null.
    - Si NO (es solo un comentario, saludo, aviso informativo): Devuelve null.

    Ejemplos:
    - "@Juan saca al perro" -> {"title": "Sacar al perro", "assignedToId": "ID_DE_JUAN"}
    - "Comprar bolsas de caca" -> {"title": "Comprar bolsas de caca", "assignedToId": null}
    - "@Maria ¿qué tal está?" -> null
    `;

    const config = {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                title: { type: Type.STRING },
                assignedToId: { type: Type.STRING, nullable: true }, // Allow null for general tasks
            },
            nullable: true
        }
    };

    try {
        const response = await generateWithFallback(apiKey, { parts: [{ text: prompt }] }, config);
        if (!response.text) return null;
        const result = JSON.parse(response.text);
        // Check only title presence, assignedToId can be null
        if (!result || !result.title) return null;
        return result;
    } catch (e) {
        console.error("Task detection failed", e);
        return null;
    }
};
